        Calculates the variance of log-probabilities per sequence.

        Signal: Variance of the log-probability distribution.
        Aggregation Principle: Computes the variance of the log-probs for each
        sequence and scales it by the sequence length to normalize the magnitude.

        Hypothesis for future: This detector assumes that hallucinations are
        characterized by high variance in model confidence (fluctuating
        predictions) rather than just low average confidence.
        """
        scores = []
        for seq_logprobs in stats["sequence_logprobs"]:
            length = len(seq_logprobs)
            if length > 0:
                # Calculate variance of the log-probabilities
                var = np.var(seq_logprobs)
                # Scale by length to normalize variance magnitude across different lengths
                # This prevents the variance from growing simply because the sequence is longer.
                score = var * length
            else:
                score = 0.0
            scores.append(score)
        return np.array(scores, dtype=np.float32)

class HallucinationDetector(Estimator):
    """
    Detector based on Weighted Confidence Decay Ratio.

    Signal: Ratio of final log-probability to weighted average log-probability.
    Aggregation: Uses weighted average for average confidence to normalize for sequence length.

    Hypothesis: Hallucinations manifest as a significant drop in confidence at the end.
    """
    def __init__(self, context: Dict[str, Any]) -> None:
        super().__init__(
            context,
            stats_dependencies=[
                "sequence_logprobs",
            ],
            level="sequence",
        )

    def __call__(self, stats: Dict[str, np.ndarray]) -> np.ndarray:
        sequence_logprobs = stats["sequence_logprobs"]

        scores = []

        for probs in sequence_logprobs:
            # Calculate weighted average log-probability (mean confidence)
            # Weighted by the log-probability itself to normalize for sequence length.
            # Avoid division by zero by ensuring weights are not all zero.
            if np.all(probs == 0):
                avg_confidence = 0.0
            else:
                avg_confidence = np.average(probs, weights=probs)

            # Extract final log-probability
            final_log_prob = probs[-1]

            # Calculate Decay Ratio
            if avg_confidence == 0:
                decay_ratio = 0.0
            else:
                decay_ratio = final_log_prob / avg_confidence

            scores.append(decay_ratio)

        return np.array(scores, dtype=np.float32)

class HallucinationDetector(Estimator):
    def __init__(self, context: Dict[str, Any]) -> None:
        super().__init__(
            context,
            stats_dependencies=[
                "sequence_logprobs",
            ],
            level="sequence",
        )

    def __call__(self, stats: Dict[str, np.ndarray]) -> np.ndarray:
        """
        Calculates the Peak-to-Average Ratio of Negative Log-Probabilities.

        Aggregation Principle: For each sequence, compute max(sequence_logprobs) / mean(sequence_logprobs).
        This isolates the most uncertain token relative to the overall confidence.

        Hypothesis for future: Hallucinations are characterized by a high variance in confidence,
        specifically a single low-probability token (high peak) amidst generally confident text.
        """
        scores = []
        for seq_logprobs in stats["sequence_logprobs"]:
            length = len(seq_logprobs)
            if length > 0:
                max_nll = np.max(seq_logprobs)
                mean_nll = np.mean(seq_logprobs)
                # Avoid division by zero if all tokens have 0 logprob (unlikely)
                if mean_nll == 0:
                    par = 0.0
                else:
                    par = max_nll / mean_nll
            else:
                par = 0.0
            scores.append(par)
        return np.array(scores, dtype=np.float32)
